DROP TABLE IF EXISTS `processo_administrativo_designacoes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `processo_administrativo_designacoes` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `processo_administrativo_id` int unsigned NOT NULL,
  `usuario_id` int unsigned NOT NULL,
  `designado_por` int unsigned DEFAULT NULL COMMENT 'Administrador/gestor que designou',
  `observacao` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pad_processo_usuario` (`processo_administrativo_id`,`usuario_id`),
  KEY `ix_pad_usuario` (`usuario_id`),
  KEY `fk_pad_designado_por` (`designado_por`),
  CONSTRAINT `fk_pad_designado_por` FOREIGN KEY (`designado_por`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_pad_processo` FOREIGN KEY (`processo_administrativo_id`) REFERENCES `processos_administrativos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_pad_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
