  `tipo` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Especie, ex.: Sentenca',
  `classificacao` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SENTENCA | DECISAO | ACORDAO | DESPACHO | EMBARGOS; NULL = nao decisoria',
