DROP TABLE IF EXISTS `processo_judicial_movimentacoes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `processo_judicial_movimentacoes` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `processo_judicial_id` int unsigned NOT NULL,
  `data_movimentacao` date DEFAULT NULL,
  `hora` time DEFAULT NULL,
  `tipo` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MOVIMENTO' COMMENT 'MOVIMENTO | DOCUMENTO',
  `descricao` text COLLATE utf8mb4_unicode_ci COMMENT 'Texto do movimento processual',
  `documento_id` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Numero do documento juntado, ex.: 249562011',
  `documento_tipo` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Especie do documento, ex.: Sentenca',
  `natureza` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Interno | Externo | Polo passivo | Movimento processual lancado',
  `origem` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SISTEMA | INTERNO | POLO_ATIVO | POLO_PASSIVO | EXTERNO | OUTROS',
  `ordem` smallint unsigned NOT NULL DEFAULT '0' COMMENT '0 = mais recente',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_pjm_processo` (`processo_judicial_id`,`ordem`),
  KEY `ix_pjm_tipo` (`tipo`),
  KEY `ix_pjm_data` (`data_movimentacao`),
  CONSTRAINT `fk_pjm_processo_judicial` FOREIGN KEY (`processo_judicial_id`) REFERENCES `processos_judiciais` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=216 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

