--
-- Table structure for table `processos_administrativos`
--

DROP TABLE IF EXISTS `processos_administrativos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `processos_administrativos` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `protocolo` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ex.: SEPLAG-PRO-2026/16696',
  `data_abertura` date DEFAULT NULL,
  `objeto` text COLLATE utf8mb4_unicode_ci,
  `procedimento` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Ex.: Fornecimento de Produto de Saude, Ressarcimento Interfederativo',
  `origem` enum('MANUAL','SIGADOC') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL',
  `url_origem` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `extrator_versao` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `data_extracao` datetime DEFAULT NULL,
  `situacao` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AGUARDANDO_ANDAMENTO | SOBRESTADO | ARQUIVADO | EM_TRANSITO | OUTRA',
  `situacao_descricao` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Rotulo oficial do SIGADOC, ex.: Arquivo Corrente',
  `responsavel_nome` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Agente publico com o processo',
  `responsavel_matricula` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `responsavel_lotacao` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Sigla da lotacao',
  `responsavel_lotacao_nome` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pa_protocolo` (`protocolo`),
  KEY `ix_pa_data_abertura` (`data_abertura`),
  KEY `ix_pa_created_at` (`created_at`),
  KEY `ix_pa_situacao` (`situacao`),
  KEY `ix_pa_procedimento` (`procedimento`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
