  `extrator_versao` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `data_extracao` datetime DEFAULT NULL,
  `data_ultima_atualizacao` date DEFAULT NULL COMMENT 'Ultima atualizacao informada pela fonte',
  `historico_completo` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = a cronologia importada cobre todo o processo; 0 = parcial (timeline paginada)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
